from core import R,load,dump
import datetime,hashlib,shutil
old=R/'round2';Q=R/'round3';assert not Q.exists()
for sub in ['configs','state','src','rtl','graphs','results','logs','build','reports','tools']:(Q/sub).mkdir(parents=True,exist_ok=True)
plan=dict(round=3,registered=datetime.datetime.now().astimezone().isoformat(),question='Is there incremental value from numerical-error freedom beyond an otherwise identical exact-output relation optimizer, especially for original 5/6-input pairs sharing fewer than five inputs?',cases=load(old/'configs/plan.json')['cases'],methods=['exact_joint','serial','budget_joint'],baselines=['exact_joint','serial'],innovations=['budget_joint'],source='identical R2 seed graphs, no new mapping or best-result substitution',candidates=dict(total_cap=24,controls=8,control_order='R2 admitted joint choices in admission order, then remaining R2 pair indices',strict_new_cap=16,strict_rules='both roots LUT5/LUT6, common inputs <=4, union 6..8, independent roots, not same original physical dual primitive',strict_rank='descending sum of original fanins, descending common inputs, ascending union, depth and names',degree_cap=4,no_fill_if_strict_pool_short=True),function_search=dict(shared_pinsets='up to eight 5-subsets, prioritize retaining common inputs then lexicographic net ids',selector='constant one or each remaining union input',output_roles=['f6','g6'],serial='both first-six and first-five orders for real selector; both output orders for constant selector; first edit must itself pass the WCE constraint',joint='exact same constrained relation/support solver for exact_joint and budget_joint; exact has output change bound zero, budget has registered numerical WCE bound',local_prefilter='retain eight legal configurations per method by sum of half-table support sizes, max support, local relation error, HD, and stable pins/init order',global_prefilter='rank retained configurations by existing structural cost; complete top two with 1024 independent-half support masks',global_admission='same one-pass matching and whole-domain check; exact_joint must additionally have max output change from seed zero'),context='sqrt complete domains; multipliers 2^16 deterministic sample proposal only; full-domain final admission for all methods plus truncation endpoint argument',max_physical_variants=12,physical='same part/flow as R2, 10ns multiplier and25ns sqrt; no new physical search directives',score=load(old/'configs/plan.json')['score'],stop='finish fixed round, analyze and score, then register justified next work; do not switch workloads mid-round',new_claim_status='unproven; R2 had zero joint-only feasible pairs and substantial exact-function gains')
dump(Q/'configs/plan.json',plan)
for c in plan['cases']:
 n=c['name'];shutil.copy2(old/f'graphs/{n}.json',Q/f'graphs/{n}.json');shutil.copy2(old/f'rtl/{n}.xdc',Q/f'rtl/{n}.xdc')
dump(Q/'state/registered_inputs.json',{p.relative_to(Q).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()for p in Q.rglob('*')if p.is_file()})
c=load(R/'state/campaign.json');c.update(status='ROUND3_REGISTERED',active_round=3,root=str(Q),latest_progress='round3/state/progress.json');dump(R/'state/campaign.json',c);print('ROUND3 REGISTERED')
